import { writeFileSync } from "fs";
import { resolve, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const out = resolve(__dirname, "..", "src", "data", "questions.ts");

let id = 0;
const nextId = () => ++id;
const all = [];

function add(part, question, options, answerIdx, passage, passageTitle, passageBody) {
  const opts = options.map((t, i) => `\`${String.fromCharCode(65 + i)}) ${t}\``);
  const ans = String.fromCharCode(65 + answerIdx);
  let str = `{id:${nextId()},part:${part},question:\`${question}\`,options:[${opts.join(",")}],answer:\`${ans}\``;
  if (passage) str += `,passage:\`${passage}\``;
  if (passageTitle) str += `,passageTitle:\`${passageTitle}\``;
  if (passageBody) str += `,passageBody:\`${passageBody}\``;
  str += "}";
  all.push(str);
}

function o(...texts) { return texts; }
function escape(s) { return s.replace(/`/g, "\\`"); }

